package com.artcatalog.mobile;

import org.junit.Test;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;

public class RecommendationsLargeProfileTest {
    private static final class CountedTags extends ArrayList<String> {
        int reads;
        @Override public Iterator<String> iterator(){reads++;return super.iterator();}
        @Override public Object[] toArray(){reads++;return super.toArray();}
    }
    private static Post work(int id,String artist){Post p=new Post();p.source="danbooru";p.id=""+id;p.artistTag=artist;p.rating="g";p.hash=String.format(Locale.ROOT,"%032x",id);p.tags=new ArrayList<>(List.of("landscape","forest","watercolor"));return p;}
    @Test public void rankingAnUnrelatedPageDoesNotReadTheImportedLikeLibraryAgain(){List<Post> likes=new ArrayList<>();List<CountedTags> observed=new ArrayList<>();
        for(int i=1;i<=256;i++){Post p=work(i,"liked_artist_"+i);CountedTags tags=new CountedTags();tags.addAll(p.tags);p.tags=tags;likes.add(p);observed.add(tags);}
        Recommendations.Model model=Recommendations.build(likes,Map.of(),0);for(CountedTags tags:observed)tags.reads=0;
        List<Post> candidates=List.of(work(10001,"new_artist_a"),work(10002,"new_artist_b"));assertEquals(2,model.rank(candidates,List.of(),Set.of()).size());
        assertEquals("A source page must not serialize/regroup every imported Like",0,observed.stream().mapToInt(tags->tags.reads).sum());
    }
    private Set<String> keys(Post p){Set<String> result=new HashSet<>(WorkGrouping.viewedTokens(p));result.add(p.key());result.addAll(p.memberKeys);return result;}
    private List<Post> reference(List<Post> likes,List<Post> candidates){Set<String> liked=new HashSet<>();for(Post p:likes)liked.addAll(keys(p));Set<String> blocked=new HashSet<>(liked);for(Post p:CatalogLogic.merge(likes,candidates)){Set<String> tokens=keys(p);if(!Collections.disjoint(tokens,liked))blocked.addAll(tokens);}List<Post> result=new ArrayList<>();for(Post p:candidates)if(Collections.disjoint(keys(p),blocked))result.add(p);return result;}
    private void visual(Post p,String hash){p.visualHash=hash;p.visualPHash="0123456789abcdef";p.visualAspectRatio=1.25;p.tags=new ArrayList<>();p.tags.add("landscape");for(int i=0;i<15;i++)p.tags.add("neutral_detail_"+i);}
    @Test public void indexedMatchingPreservesHashVisualParentAndUploaderDecisions(){Post liked=work(1,"artist_a"),mirror=work(100,"artist_b"),variant=work(101,"artist_a"),unrelated=work(102,"artist_c");mirror.source="gelbooru";mirror.hash=liked.hash;visual(liked,"0000000000000000");visual(variant,"0000000000000001");
        List<Post> likes=new ArrayList<>(List.of(liked)),candidates=new ArrayList<>(List.of(mirror,variant,unrelated));
        Post parent=work(2,"artist_d"),separate=work(103,"artist_d");parent.groupKey=separate.groupKey="danbooru:parent:2";parent.originalUrl="https://www.pixiv.net/artworks/123456";separate.originalUrl="https://www.pixiv.net/artworks/123457";likes.add(parent);candidates.add(separate);
        Post uploaded=work(3,""),uploadedVariant=work(104,"");uploaded.source=uploadedVariant.source="rule34";uploaded.uploaderId=uploadedVariant.uploaderId="77";visual(uploaded,"1111111111111111");visual(uploadedVariant,"1111111111111110");likes.add(uploaded);candidates.add(uploadedVariant);
        assertEquals(reference(likes,candidates),Recommendations.build(likes,Map.of(),0).excludeLiked(candidates));assertEquals(List.of(unrelated,separate),Recommendations.build(likes,Map.of(),0).excludeLiked(candidates));
    }
    @Test public void indexRetainsTransitiveLikedComponentsWithDifferentCreators(){Post a=work(1,"artist_a"),b=work(2,"artist_b"),candidate=work(100,"artist_b");a.originalUrl=b.originalUrl="https://www.pixiv.net/artworks/123456";visual(b,"0000000000000000");visual(candidate,"0000000000000001");List<Post> likes=List.of(a,b),candidates=List.of(candidate);assertEquals(reference(likes,candidates),Recommendations.build(likes,Map.of(),0).excludeLiked(candidates));assertTrue(Recommendations.build(likes,Map.of(),0).excludeLiked(candidates).isEmpty());}
    @Test public void canceledBuildStopsWithoutPublishingOrReadingLikes(){Post p=work(1,"artist_a");CountedTags tags=new CountedTags();tags.addAll(p.tags);p.tags=tags;assertNull(Recommendations.build(List.of(p),Map.of(),0,()->false));assertEquals(0,tags.reads);AtomicInteger calls=new AtomicInteger();List<Post> likes=new ArrayList<>();for(int i=0;i<128;i++)likes.add(work(i+1,"artist_"+i));assertNull(Recommendations.build(likes,Map.of(),0,()->calls.incrementAndGet()<5));assertTrue(calls.get()>=5);}
    @Test public void calibrationReusesProfileAndProducesTheSameWeightsQueriesAndOrder(){List<Post> likes=new ArrayList<>(),background=new ArrayList<>(),candidates=new ArrayList<>();for(int i=0;i<32;i++){likes.add(work(i+1,"artist_"+i));background.add(work(100+i,"background_"+i));}for(int i=0;i<8;i++)candidates.add(work(200+i,"new_"+i));Recommendations.Model model=Recommendations.build(likes,Map.of(),0),recalibrated=model.recalibrate(background,()->true),rebuilt=Recommendations.build(likes,Map.of(),0,background);assertEquals(rebuilt.weights,recalibrated.weights);assertEquals(rebuilt.queryGroups,recalibrated.queryGroups);assertEquals(rebuilt.rank(candidates,List.of(),Set.of()),recalibrated.rank(candidates,List.of(),Set.of()));assertNull(model.recalibrate(background,()->false));}
    @Test public void asynchronousCreatorAndFingerprintEnrichmentUpdatesOnlyTheMatchingIndex(){Post liked=work(1,""),candidate=work(100,"artist_a");Recommendations.Model model=Recommendations.build(List.of(liked),Map.of(),0);liked.artistTag="artist_a";liked.artistTags=List.of(liked.artistTag);visual(liked,"0000000000000000");visual(candidate,"0000000000000001");assertEquals(reference(List.of(liked),List.of(candidate)),model.excludeLiked(List.of(candidate)));assertTrue(model.excludeLiked(List.of(candidate)).isEmpty());}
    @Test public void sameLengthVisualSampleReplacementAndInPlaceCreatorChangesAreObserved() throws Exception {Post liked=work(1,""),candidate=work(100,"artist_b");visual(candidate,"0000000000000001");liked.visualSamples.put(new org.json.JSONObject().put("hash","0000000000000000").put("creator","artist_a").put("source","danbooru").put("tags",new org.json.JSONArray(candidate.tags)));Recommendations.Model model=Recommendations.build(List.of(liked),Map.of(),0);assertEquals(List.of(candidate),model.excludeLiked(List.of(candidate)));liked.visualSamples.getJSONObject(0).put("creator","artist_b").put("perceptualHash",candidate.visualPHash).put("aspectRatio",candidate.visualAspectRatio);assertEquals(reference(List.of(liked),List.of(candidate)),model.excludeLiked(List.of(candidate)));assertTrue(model.excludeLiked(List.of(candidate)).isEmpty());liked.visualSamples.put(0,new org.json.JSONObject().put("hash","0000000000000000").put("creator","artist_c").put("source","danbooru").put("tags",new org.json.JSONArray(candidate.tags)));assertEquals(reference(List.of(liked),List.of(candidate)),model.excludeLiked(List.of(candidate)));assertEquals(List.of(candidate),model.excludeLiked(List.of(candidate)));}
    @Test public void paddedLegacyUploaderUsesExactlyTheSameVisualEligibilityAsGrouping(){Post liked=work(1,""),candidate=work(100,"");liked.source=candidate.source="rule34";liked.uploaderId=candidate.uploaderId=" anonymous ";visual(liked,"0000000000000000");visual(candidate,"0000000000000001");assertEquals(reference(List.of(liked),List.of(candidate)),Recommendations.build(List.of(liked),Map.of(),0).excludeLiked(List.of(candidate)));assertTrue(Recommendations.build(List.of(liked),Map.of(),0).excludeLiked(List.of(candidate)).isEmpty());}
    @Test public void newlyBridgedLikedGroupRetainsPublicationConflictGuards(){Post a=work(1,"artist_a"),b=work(2,"artist_b"),candidate=work(100,"artist_b");a.originalUrl="https://www.pixiv.net/artworks/123456";candidate.originalUrl="https://www.pixiv.net/artworks/123457";visual(b,"0000000000000000");visual(candidate,"0000000000000001");List<Post> likes=List.of(a,b),page=List.of(candidate);Recommendations.Model model=Recommendations.build(likes,Map.of(),0);b.groupKey="danbooru:parent:1";assertEquals(List.of(candidate),reference(likes,page));assertEquals(reference(likes,page),model.excludeLiked(page));}
    @Test public void replacedStrongMetadataDoesNotLeaveAnObsoleteExclusionToken(){Post liked=work(1,"artist_a"),oldMirror=work(100,"artist_b"),newMirror=work(101,"artist_c");oldMirror.hash=liked.hash;Recommendations.Model model=Recommendations.build(List.of(liked),Map.of(),0);assertTrue(model.excludeLiked(List.of(oldMirror)).isEmpty());liked.hash=newMirror.hash;assertEquals(reference(List.of(liked),List.of(oldMirror,newMirror)),model.excludeLiked(List.of(oldMirror,newMirror)));assertEquals(List.of(oldMirror),model.excludeLiked(List.of(oldMirror,newMirror)));}
    @Test public void collidingJavaStringHashesStillRefreshChangedCreatorMetadata(){assertEquals("Aa".hashCode(),"BB".hashCode());Post liked=work(1,"Aa"),candidate=work(100,"BB");liked.artistTags=List.of(liked.artistTag);visual(liked,"0000000000000000");visual(candidate,"0000000000000001");Recommendations.Model model=Recommendations.build(List.of(liked),Map.of(),0);liked.artistTag="BB";liked.artistTags=List.of(liked.artistTag);assertEquals(reference(List.of(liked),List.of(candidate)),model.excludeLiked(List.of(candidate)));assertTrue(model.excludeLiked(List.of(candidate)).isEmpty());}
}
